import { v4 as uuidv4 } from 'uuid';

import PsyanimAnimationClip from '../core/PsyanimAnimationClip.js';
import PsyanimDebug from '../core/PsyanimDebug.js';

/**
 *  Query types
 */

class TrailMetadataQuery {

    constructor(db) {

        this._db = db;

        this._trialMetadata = [];
    }

    execute(docIDs) {

        this._docCount = docIDs.length;
        this._receivedDocCount = 0;

        let promise = new Promise((resolve, reject) => {
            
            this._resolve = resolve;
            this._reject = reject;
        });

        for (let i = 0; i < this._docCount; ++i)
        {
            let docRef = this._db.collection('trial-metadata').doc(docIDs[i]);

            docRef.get()
                .then((doc) => {
                    
                    if (doc.exists)
                    {
                        this._trialMetadata.push({
                            data: doc.data().data,
                            id: doc.id
                        });

                        this._receivedDocCount++;

                        this._checkIfReceivedAllDocs();
                    }
                    else
                    {
                        let errorMsg = "ERROR: document id not found: " + docIDs[i];

                        this._reject(new Error(errorMsg));
                    }
                });
        };

        return promise;
    }

    _checkIfReceivedAllDocs() {

        if (this._receivedDocCount == this._docCount)
        {
            this._resolve(this._trialMetadata);
        }
    }
}

class AnimationClipQuery {

    constructor(db) {

        this._db = db;
        
        this._clipData = [];
    }

    execute(clipIDs) {

        this._clipCount = clipIDs.length;
        this._receivedClipCount = 0;

        let promise = new Promise((resolve, reject) => {

            this._resolve = resolve;
            this._reject = reject;
        });

        for (let i = 0; i < this._clipCount; ++i)
        {
            let docRef = this._db.collection('animation-clips').doc(clipIDs[i]);

            docRef.get().then((doc) => {
                
                if (doc.exists) 
                {
                    let clip = new PsyanimAnimationClip(doc.data().data);

                    this._clipData.push({
                        id: doc.id,
                        clip: clip
                    });

                    this._receivedClipCount++;

                    this._checkIfReceivedAllClips();
                }
                else
                {
                    let errorMsg = "ERROR: document id not found: " + clipIDs[i];

                    this._reject(new Error(errorMsg));
                }
            });
        };

        return promise;
    }

    _checkIfReceivedAllClips() {

        if (this._receivedClipCount == this._clipCount)
        {
            this._resolve(this._clipData);
        }
    }
}

export default class PsyanimFirebaseClientBase {

    constructor(firebaseConfig) {

        this._initFirebase(firebaseConfig);

        this._db = this._initFirestore();
    }

    _initFirebase(firebaseConfig) {

        PsyanimDebug.error("Can not instantiate PsyanimFirebaseClientBase directly! " + 
            "Must extend this clas and override initFirebase() method!");

        return null;
    }

    _initFirestore() {

        PsyanimDebug.error("Can not instantiate PsyanimFirebaseClientBase directly! " + 
            "Must extend this clas and override _initFirestore() method!");

        return null;
    }

    // TODO: should this be a part of the browser client only or will it work for admin sdk too?
    useEmulator() {

        if (location.hostname === '127.0.0.1' || location.hostname === 'localhost')
        {
            console.warn("Using local firebase emulator!");
            this._db.useEmulator('127.0.0.1', 8080);
        }
        else
        {
            console.error("Can't start emulator if not running locally!");
        }
    }

    get db() {

        return this._db;
    }

    get serverTimestamp() {

        return this._getServerTimestamp();
    }

    addAnimationClip(data) {

        let newId = uuidv4();

        this.db
            .collection('animation-clips')
            .doc(newId)
            .set({
                data: data,
                lastTimeModified: this.serverTimestamp
            })
            .then(() => console.log("Animation clip document written!"))
            .catch((error) => console.error('Error adding document: ', error));

        return newId;
    }

    addAgentStateLog(data) {

        let newId = uuidv4();

        this.db
            .collection('state-logs')
            .doc(newId)
            .set({
                data: data,
                time: this.serverTimestamp
            })
            .then(() => console.log('Agent state log written!'))
            .catch((error) => console.error('Error adding document: ', error));

        return newId;
    }

    addExperimentTrialMetadata(data) {
        
        let newId = uuidv4();

        this.db
            .collection('trial-metadata')
            .doc(newId)
            .set({
                data: data,
                time: this.serverTimestamp
            })
            .then(() => console.log("Experiment metadata document written!"))
            .catch((error) => console.error("Error adding document: ", error));

        return newId;
    }

    addExperimentJsPsychData(data, docID = null) {

        if (!docID)
        {
            docID = uuidv4();
        }

        this.db
            .collection('jspsych-experiment-data')
            .doc(docID)
            .set({
                data: data,
                time: this.serverTimestamp
            })
            .then(() => console.log('JsPsych Experiment Data written!'))
            .catch((error) => console.error("Error adding document: ", error));

        return docID;
    }

    writeSessionLogData(docId, data) {

        this.db
            .collection('session-logs')
            .doc(docId)
            .set({
                data: data,
                time: this.serverTimestamp
            })
            .then(() => console.log("Session logs document written!"))
            .catch((error) => console.error("Error adding document: ", error));
    }

    /**
     *  TODO: switch to returning a promise to make client code simpler
     * 
     * @param {*} callback - receives a clipData array containing clip IDs and data
     */
    getAllAnimationClipAsync(callback) {

        this.db
            .collection("animation-clips").get()
            .then((querySnapshot) => {

                let clipData = [];

                querySnapshot.forEach((doc) => {

                    let clip = new PsyanimAnimationClip(doc.data().data);

                    clipData.push({
                        id: doc.id,
                        clip: clip
                    });
                });

                callback(clipData);
            });
    }

    getAnimationClipsByIdAsync(clipIDs) {

        let query = new AnimationClipQuery(this.db);

        return query.execute(clipIDs);
    }

    // TODO: switch to returning a promise to make calling code simpler
    getAllExperimentMetadataAsync(callback) {

        this.db
            .collection('trial-metadata').get()
            .then((querySnapshot) => {

                let experimentMetadata = [];

                querySnapshot.forEach((doc) => {

                    experimentMetadata.push(doc);
                });

                callback(experimentMetadata);
            });
    }

    getTrialMetadataByIdAsync(docIDs) {

        let query = new TrailMetadataQuery(this.db);

        return query.execute(docIDs);
    }
}